import { Component, TemplateRef, computed, inject, signal, viewChild } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { NgTemplateOutlet } from '@angular/common';
import { FormsModule } from '@angular/forms';
import {
  TablerIconComponent, IconArrowsMaximize,
  IconDownload, IconCheck, IconX, IconEye, IconCalendarStats,
} from '@tabler/icons-angular';
import {
  HrmAppShell, HrmButton, HrmSegmented, HrmInput,
  HrmDataView, HrmGridColumn, HrmBoardGroup, HrmStatusCell, HrmTag, HrmUserCell,
  HrmListPage, HrmListPageTabs, HrmDetailPeek, HrmPeekMode, HrmActionBar, HrmActionBarItem,
  HrmWorkflowStatus, HRM_WORKFLOW_ACTIONS,
} from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont } from '../../../doc/sg-blocks';
import { SgRequestDetail } from './sg-request-detail';
import { SgTemplateSideNav } from './_template-side-nav';
import { requestRows, REQ_TYPES, ReqRow, ReqStatus, reqStatusMeta } from './_requests';

type Tab = 'pending' | 'processed' | 'all';

/** Doc page · Chế độ xem dữ liệu — PHÊ DUYỆT (Template) — biến thể "người duyệt": hộp duyệt đơn
 *  từ (tab Chờ duyệt / Đã xử lý / Tất cả) đa chế độ (Bảng/Thẻ/Kanban theo trạng thái) + duyệt/từ
 *  chối NGAY trên dòng, duyệt HÀNG LOẠT, và chi tiết có cụm hành động quy trình chuẩn DS
 *  (HRM_WORKFLOW_ACTIONS: Duyệt · Từ chối · Yêu cầu thay đổi). Self-contained, design token. */
@Component({
  selector: 'sg-template-request-approval',
  imports: [
    NgTemplateOutlet, FormsModule, TablerIconComponent,
    HrmAppShell, SgTemplateSideNav, HrmButton, HrmSegmented, HrmInput,
    HrmDataView, HrmStatusCell, HrmTag, HrmUserCell, HrmListPage, HrmListPageTabs, HrmDetailPeek, HrmActionBar,
    SgRequestDetail, SgDoc, SgUse, SgDo, SgDont,
  ],
  template: `
    @if (preview) {
      <div class="lp-desktop lp-desktop--full"><ng-container *ngTemplateOutlet="screen" /></div>
    } @else {
    <sg-doc category="Template" title="Chế độ xem dữ liệu — Phê duyệt"
      desc="Biến thể 'người duyệt' của template danh sách: hộp duyệt đơn từ theo tab (Chờ duyệt / Đã xử lý / Tất cả), đa chế độ, duyệt/từ chối ngay trên dòng + hàng loạt, chi tiết có cụm hành động quy trình chuẩn DS.">
      <div sgOverview>
        <div class="lp-desktop"><ng-container *ngTemplateOutlet="screen" /></div>
        <div class="lp-full">
          <a class="lp-full-link" href="/preview/request-approval" target="_blank" rel="noopener">
            <hrm-button variant="default"><tabler-icon [icon]="maximize" [size]="16" /> Mở toàn màn hình</hrm-button>
          </a>
        </div>
      </div>
      <div sgUsage>
        <sg-use purpose="Cho NGƯỜI DUYỆT xử lý hàng loạt bản ghi chờ quyết định (đơn từ, đề xuất): duyệt/từ chối nhanh trên dòng hoặc mở chi tiết để quyết định có ngữ cảnh."
          [when]="when"
          behavior="Mặc định lọc 'Chờ duyệt'; mỗi dòng có nút Duyệt/Từ chối; chọn nhiều → duyệt/từ chối hàng loạt; chi tiết dùng cụm hành động State Machine (Duyệt · Từ chối · Yêu cầu thay đổi)."
          avoid="Không dùng cho người tạo đơn (dùng biến thể Đăng ký); không để lẫn đơn Nháp chưa gửi vào hộp duyệt." />
      </div>
      <div sgBest>
        <sg-do>Mặc định vào tab 'Chờ duyệt' — đưa việc cần xử lý lên trước.</sg-do>
        <sg-do>Cho phép duyệt/từ chối ngay trên dòng + hàng loạt để xử lý nhanh.</sg-do>
        <sg-dont>Đừng ẩn lý do/ngữ cảnh — người duyệt cần đủ thông tin để quyết định.</sg-dont>
      </div>
    </sg-doc>
    }

    <ng-template #screen>
      <hrm-app-shell contentPad="none">
        <sg-template-side-nav appSideNav selectedKey="requests" />

        <hrm-list-page title="Phê duyệt đơn từ" [subtitle]="subtitle()"
          [total]="mode() === 'table' ? filteredRows().length : 0" [(pageIndex)]="page" [pageSize]="10" [panel]="mode() === 'table'">

          <div headerActions class="lp-hdr">
            <hrm-segmented [options]="viewSegments" [(ngModel)]="modeModel" size="md" />
          </div>

          <!-- Tab lọc trạng thái xử lý -->
          <div lpTabs class="lp-tabsrow">
            <hrm-segmented [options]="tabSegments()" [(ngModel)]="tabModel" size="md" />
          </div>

          <div filters class="tbx">
            @if (selKeys().length === 0) {
              <hrm-input [(ngModel)]="kwModel" placeholder="Tìm mã đơn, người gửi…" style="width:260px" />
            } @else {
              <button type="button" class="bx-clear" aria-label="Bỏ chọn" (click)="selKeys.set([])"><tabler-icon [icon]="close" [size]="16" /></button>
              <span class="bx-count">Đã chọn <b>{{ selKeys().length }}</b> đơn chờ duyệt</span>
            }
          </div>
          <div actions class="tbx">
            @if (selKeys().length === 0) {
              <hrm-button variant="default"><tabler-icon [icon]="download" [size]="18" /> Xuất</hrm-button>
            } @else {
              <hrm-button variant="primary" (click)="bulk('approve')"><tabler-icon [icon]="check" [size]="16" /> Duyệt</hrm-button>
              <hrm-button variant="default" [danger]="true" (click)="bulk('reject')"><tabler-icon [icon]="close" [size]="16" /> Từ chối</hrm-button>
            }
          </div>

          <hrm-data-view
            [columns]="cols()" [data]="filteredRows()" rowKey="id" tableMinWidth="880px"
            [selectable]="true" [selectedKeys]="selKeys()" (selectedKeysChange)="selKeys.set($event)"
            [modes]="['table','card','kanban','gantt']" [mode]="mode()" (modeChange)="mode.set($any($event))"
            groupBy="status" [boardGroups]="boardGroups" [boardCardTemplate]="dvCard"
            startField="start" endField="end" ganttLabelField="applicant" ganttHeader="Người gửi" ganttDateHeader="Thời gian"
            [ganttLabelTemplate]="gtLabel" [ganttBarTone]="ganttTone"
            [cardTemplate]="dvCard"
            (openRecord)="openDetail($any($event))"
            tableLabel="Bảng" cardLabel="Thẻ" kanbanLabel="Kanban" ganttLabel="Gantt" />

          <hrm-detail-peek lpDetail [(open)]="peekOpen" [(peekMode)]="peekMode"
            [modes]="['master','side','center','full','tab']" [expandable]="false"
            [title]="selectedRow()?.code ?? ''" [content]="reqDetailTpl() ?? null" [footer]="peekFooter"
            [modeLabels]="peekLabels" [routeUrl]="peekRoute()"
            switchLabel="Đổi cách hiển thị" expandLabel="Mở toàn trang" closeLabel="Đóng" resizeLabel="Kéo đổi độ rộng" />
          <span pagerInfo>Hiển thị {{ filteredRows().length }} đơn</span>
        </hrm-list-page>
      </hrm-app-shell>
    </ng-template>

    <ng-template #reqDetail>
      @if (selectedRow(); as r) { <sg-request-detail [req]="r" /> }
    </ng-template>

    <!-- FOOTER chi tiết — cụm hành động QUY TRÌNH chuẩn DS theo trạng thái. -->
    <ng-template #peekFooter>
      @if (selectedRow(); as r) {
        <hrm-action-bar [actions]="wfActions(r.status)" moreLabel="Thêm" (action)="applyWf(r, $event)" />
      }
    </ng-template>

    <!-- Cells -->
    <ng-template #userCell let-r><hrm-user-cell [name]="$any(r.applicant)" [sub]="$any(r.dept)" [colorful]="true" [avatarSize]="30" /></ng-template>
    <ng-template #codeCell let-r><span class="c-code">{{ r.code }}</span></ng-template>
    <ng-template #typeCell let-r><hrm-tag color="blue">{{ REQ_TYPES[r.type] }}</hrm-tag></ng-template>
    <ng-template #timeCell let-r><span class="c-mut">{{ r.from }} → {{ r.to }}</span></ng-template>
    <ng-template #daysCell let-r><span>{{ r.days }} {{ r.unit }}</span></ng-template>
    <ng-template #sentCell let-r><span class="c-mut">{{ r.submittedAt }}</span></ng-template>
    <ng-template #statusCell let-r>
      <hrm-status [status]="meta(r.status).tone" [label]="meta(r.status).vi" variant="badge" [dot]="true" />
    </ng-template>
    <!-- Cột hành động — nút MÀU NGỮ NGHĨA (duyệt xanh · từ chối đỏ), đồng bộ ngôn ngữ màu với footer. -->
    <ng-template #actionCell let-r>
      @if (r.status === 'pending') {
        <span class="aq">
          <button type="button" class="aq-btn aq-ok" aria-label="Duyệt" title="Duyệt"
            (click)="row(r, 'approve'); $event.stopPropagation()"><tabler-icon [icon]="check" [size]="17" /></button>
          <button type="button" class="aq-btn aq-no" aria-label="Từ chối" title="Từ chối"
            (click)="row(r, 'reject'); $event.stopPropagation()"><tabler-icon [icon]="close" [size]="17" /></button>
        </span>
      } @else {
        <button type="button" class="aq-btn aq-view" aria-label="Xem chi tiết" title="Xem chi tiết"
          (click)="openDetail(r); $event.stopPropagation()"><tabler-icon [icon]="eye" [size]="17" /></button>
      }
    </ng-template>

    <ng-template #dvCard let-r>
      <div class="rc">
        <div class="rc-top">
          <hrm-user-cell [name]="$any(r.applicant)" [sub]="$any(r.dept)" [colorful]="true" [avatarSize]="34" />
          <hrm-status [status]="meta(r.status).tone" [label]="meta(r.status).vi" variant="badge" [dot]="true" />
        </div>
        <div class="rc-line"><span class="c-code">{{ r.code }}</span><hrm-tag color="blue">{{ REQ_TYPES[r.type] }}</hrm-tag></div>
        <div class="rc-row"><tabler-icon [icon]="icCal" [size]="14" /><span>{{ r.from }} → {{ r.to }} · {{ r.days }} {{ r.unit }}</span></div>
        @if (r.status === 'pending') {
          <div class="rc-foot">
            <hrm-button size="sm" variant="primary" (click)="row(r, 'approve'); $event.stopPropagation()"><tabler-icon [icon]="check" [size]="15" /> Duyệt</hrm-button>
            <hrm-button size="sm" variant="primary" [danger]="true" (click)="row(r, 'reject'); $event.stopPropagation()"><tabler-icon [icon]="close" [size]="15" /> Từ chối</hrm-button>
          </div>
        }
      </div>
    </ng-template>

    <!-- Nhãn trái Gantt — người gửi (avatar + tên + phòng ban). -->
    <ng-template #gtLabel let-r>
      <hrm-user-cell [name]="$any(r.applicant)" [sub]="$any(r.dept)" [colorful]="true" [avatarSize]="26" />
    </ng-template>
  `,
  styles: [`
    .lp-desktop { height: 760px; border: 1px solid var(--border-sub); border-radius: var(--radius-xl); overflow: hidden; box-shadow: var(--shadow-regular-sm); }
    .lp-desktop--full { height: 100vh; border: 0; border-radius: 0; box-shadow: none; }
    .lp-full { margin-top: 14px; } .lp-full-link { text-decoration: none; }
    .lp-desktop ::ng-deep .shell-content { padding: 0; display: flex; flex-direction: column; min-height: 0; }
    .lp-desktop ::ng-deep .shell-content hrm-list-page { flex: 1 1 auto; min-height: 0; }
    .lp-desktop ::ng-deep hrm-data-view .dv-bar { display: none; }
    .lp-desktop ::ng-deep .ant-table-tbody > tr > td, .lp-desktop ::ng-deep .ant-table-thead > tr > th { white-space: nowrap; }
    :host ::ng-deep .ant-tag { margin: 0; }

    .lp-hdr { display: flex; align-items: center; justify-content: flex-end; gap: var(--space-2); }
    .lp-tabsrow { display: flex; }
    .tbx { display: flex; align-items: center; gap: var(--space-2); min-width: 0; }
    .bx-clear { display: grid; place-items: center; width: 28px; height: 28px; border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); }
    .bx-clear:hover { background: var(--bg-surface-subtle); color: var(--text-strong); }
    .bx-count { font-size: var(--fs-13); color: var(--text-body); background: var(--primary-bg-subtle); padding: 4px 10px; border-radius: var(--radius-full); white-space: nowrap; }
    .bx-count b { color: var(--primary-base); }

    /* Cột hành động — nút icon SOLID theo TONE (đồng bộ treatment với footer detail: duyệt=primary,
       từ chối=error). Rule: tone quyết định màu (như status-cell); mọi surface dùng CÙNG solid. */
    .aq { display: inline-flex; gap: var(--space-2, 8px); }
    .aq-btn { display: inline-flex; align-items: center; justify-content: center; width: 34px; height: 34px; border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub); transition: filter .12s, background-color .12s, border-color .12s, color .12s; }
    .aq-ok { background: var(--primary-base); border-color: var(--primary-base); color: var(--static-white, #fff); }
    .aq-no { background: var(--error-base); border-color: var(--error-base); color: var(--static-white, #fff); }
    .aq-ok:hover, .aq-no:hover { filter: brightness(0.95); }
    .aq-view:hover { border-color: var(--primary-base); color: var(--primary-base); }

    .c-code { font-family: var(--font-mono, ui-monospace, monospace); font-size: var(--fs-13); color: var(--text-strong); font-weight: var(--font-medium, 500); }
    .c-mut { font-size: var(--fs-13); color: var(--text-sub); }

    .rc { display: flex; flex-direction: column; gap: var(--space-2, 8px); }
    .rc-top { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-2); }
    .rc-line { display: flex; align-items: center; gap: var(--space-2, 8px); }
    .rc-row { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: var(--fs-12); color: var(--text-sub); }
    .rc-row tabler-icon { flex: none; color: var(--text-soft); }
    .rc-foot { display: flex; gap: var(--space-2, 8px); padding-top: var(--space-2, 8px); border-top: 1px solid var(--border-soft); }
  `],
})
export class SgTemplateRequestApproval {
  protected readonly preview = inject(ActivatedRoute).snapshot.data['preview'] === true;
  protected readonly REQ_TYPES = REQ_TYPES;
  protected meta(s: ReqStatus) { return reqStatusMeta(s); }

  protected readonly maximize = IconArrowsMaximize;
  protected readonly download = IconDownload;
  protected readonly check = IconCheck;
  protected readonly close = IconX;
  protected readonly icCal = IconCalendarStats;
  protected readonly when = ['Hộp duyệt đơn từ / đề xuất', 'Xử lý hàng loạt bản ghi chờ quyết định', 'Vai trò quản lý / người phê duyệt'];

  // ── state ──
  protected readonly rows = signal<ReqRow[]>(requestRows());
  protected readonly mode = signal<'table' | 'card' | 'kanban' | 'gantt'>('table');
  protected get modeModel() { return this.mode(); }
  protected set modeModel(v: string) { this.mode.set(v as 'table' | 'card' | 'kanban' | 'gantt'); }
  protected page = 1;

  private readonly _kw = signal('');
  protected get kwModel() { return this._kw(); }
  protected set kwModel(v: string) { this._kw.set(v); }
  private readonly _tab = signal<Tab>('pending');
  protected get tabModel() { return this._tab(); }
  protected set tabModel(v: string) { this._tab.set(v as Tab); this.selKeys.set([]); }

  /** Đơn đã gửi (bỏ Nháp — chưa vào hộp duyệt). */
  private readonly submitted = computed(() => this.rows().filter((r) => r.status !== 'draft'));
  private readonly pendingCount = computed(() => this.rows().filter((r) => r.status === 'pending').length);
  protected readonly subtitle = computed(() => `${this.pendingCount()} đơn chờ bạn duyệt`);
  protected readonly tabSegments = computed(() => [
    { label: `Chờ duyệt (${this.pendingCount()})`, value: 'pending' },
    { label: 'Đã xử lý', value: 'processed' },
    { label: 'Tất cả', value: 'all' },
  ]);

  protected readonly filteredRows = computed<ReqRow[]>(() => {
    const kw = this._kw().trim().toLowerCase();
    const tab = this._tab();
    return this.submitted().filter((r) => {
      if (tab === 'pending' && r.status !== 'pending') return false;
      if (tab === 'processed' && r.status === 'pending') return false;
      if (kw && !`${r.code} ${r.applicant} ${REQ_TYPES[r.type]}`.toLowerCase().includes(kw)) return false;
      return true;
    });
  });

  protected readonly viewSegments = [
    { label: 'Bảng', value: 'table' }, { label: 'Thẻ', value: 'card' }, { label: 'Kanban', value: 'kanban' }, { label: 'Gantt', value: 'gantt' },
  ];
  /** Tông màu thanh Gantt theo trạng thái đơn. */
  protected readonly ganttTone = (r: Record<string, unknown>): string => reqStatusMeta(r['status'] as ReqStatus).tone;
  protected readonly boardGroups: HrmBoardGroup[] = [
    { key: 'pending', label: 'Chờ duyệt', tone: 'warning' },
    { key: 'changeRequested', label: 'Yêu cầu thay đổi', tone: 'info' },
    { key: 'approved', label: 'Đã duyệt', tone: 'success' },
    { key: 'rejected', label: 'Đã từ chối', tone: 'error' },
    { key: 'pendingCancel', label: 'Chờ hủy', tone: 'warning' },
    { key: 'cancelled', label: 'Đã hủy', tone: 'error' },
  ];

  // ── row inline actions (nút màu ngữ nghĩa: duyệt xanh · từ chối đỏ · xem trung tính) ──
  protected readonly eye = IconEye;
  /** Duyệt/Từ chối nhanh 1 dòng. */
  protected row(r: ReqRow, key: 'approve' | 'reject'): void {
    this.setStatus(r.id, key === 'approve' ? 'approved' : 'rejected');
  }

  // ── bulk ──
  protected readonly selKeys = signal<unknown[]>([]);
  protected bulk(key: 'approve' | 'reject'): void {
    const ids = new Set(this.selKeys().map(Number));
    const to: ReqStatus = key === 'approve' ? 'approved' : 'rejected';
    this.rows.update((l) => l.map((r) => (ids.has(r.id) && r.status === 'pending' ? { ...r, status: to } : r)));
    this.selKeys.set([]);
  }

  // ── peek ──
  protected readonly peekOpen = signal(false);
  protected readonly peekMode = signal<HrmPeekMode>('master');
  protected readonly peekLabels: Partial<Record<HrmPeekMode, string>> = {
    master: 'Bảng + chi tiết', side: 'Cạnh danh sách', center: 'Giữa màn hình',
    full: 'Toàn trang', tab: 'Tab mới',
  };
  /** Đích Toàn trang / Tab mới — trang bản ghi độc lập (vai trò phê duyệt). */
  protected readonly peekRoute = computed(() => {
    const id = this.selectedId();
    return id == null ? '' : `/styleguide/hrm/template/request-record?id=${id}&kind=approval`;
  });
  protected readonly selectedId = signal<number | null>(null);
  protected readonly selectedRow = computed<ReqRow | null>(() => {
    const id = this.selectedId();
    return id == null ? null : this.rows().find((r) => r.id === id) ?? null;
  });
  protected readonly reqDetailTpl = viewChild<TemplateRef<any>>('reqDetail');
  protected openDetail(r: ReqRow): void { this.selectedId.set(r.id); this.peekOpen.set(true); }

  // ── workflow (State Machine chuẩn DS) ──
  private setStatus(id: number, s: ReqStatus): void {
    this.rows.update((l) => l.map((r) => (r.id === id ? { ...r, status: s } : r)));
  }
  /** Cụm hành động footer theo trạng thái = đúng các mũi tên State Machine. */
  protected wfActions(s: ReqStatus): HrmActionBarItem[] {
    if (s === 'draft') return [];
    return (HRM_WORKFLOW_ACTIONS[s as HrmWorkflowStatus] ?? []).map((a) => ({
      key: a.key, label: a.vi, tone: a.tone, icon: a.icon,
    }));
  }
  protected applyWf(r: ReqRow, key: string): void {
    if (r.status === 'draft') return;
    const act = (HRM_WORKFLOW_ACTIONS[r.status as HrmWorkflowStatus] ?? []).find((a) => a.key === key);
    if (!act || act.to === 'end') return;
    this.setStatus(r.id, act.to);
  }

  // ── table cols ──
  private readonly userCell = viewChild<TemplateRef<any>>('userCell');
  private readonly codeCell = viewChild<TemplateRef<any>>('codeCell');
  private readonly typeCell = viewChild<TemplateRef<any>>('typeCell');
  private readonly timeCell = viewChild<TemplateRef<any>>('timeCell');
  private readonly daysCell = viewChild<TemplateRef<any>>('daysCell');
  private readonly sentCell = viewChild<TemplateRef<any>>('sentCell');
  private readonly statusCell = viewChild<TemplateRef<any>>('statusCell');
  private readonly actionCell = viewChild<TemplateRef<any>>('actionCell');
  protected readonly cols = computed<HrmGridColumn[]>(() => [
    { key: 'code', title: 'Mã đơn', width: '140px', cell: this.codeCell() },
    { key: 'applicant', title: 'Người gửi', width: '220px', cell: this.userCell() },
    { key: 'type', title: 'Loại đơn', width: '150px', cell: this.typeCell() },
    { key: 'time', title: 'Thời gian', width: '190px', cell: this.timeCell() },
    { key: 'days', title: 'Số lượng', width: '100px', cell: this.daysCell() },
    { key: 'submittedAt', title: 'Ngày gửi', width: '120px', cell: this.sentCell() },
    { key: 'status', title: 'Trạng thái', width: '140px', cell: this.statusCell() },
    { key: 'act', title: '', align: 'right', width: '120px', fixed: 'right', cell: this.actionCell() },
  ]);
}
